// The records Kobble keeps about a product's people: where signals come
// from, the signals themselves, the personas and the customers who are like
// them, their stories, the problems the stories break at and the real
// problems behind those, the ideas for them, the versions of each idea, and
// the GitHub issues they became with whether they worked. Every record says
// where it came from; a record is checked as a whole in check.ts. What can be
// worked out from the records (a problem's state, how well a story is known)
// is never stored (derive.ts).
import { z } from "zod";
const id = z.string().min(1);
const text = z.string().min(1);
// A GitHub issue's number.
const issue = z.number().int().positive();
// Who wrote or confirmed something: the kobold (a suggestion, until a person
// confirms it) or a team member, by name.
export const KOBOLD = "kobold";
const by = z.string().min(1);
// What a source is: what people say or write (feedback, support, interviews,
// reviews, questions), how they use the product, machine errors, alerts
// (a dependency's security update), or runs by a persona, which are checks
// for the team and never evidence about real people.
export const SOURCE_KINDS = [
    "people",
    "usage",
    "errors",
    "alerts",
    "personaRuns",
];
export const sourceSchema = z.strictObject({
    id,
    name: text,
    kind: z.enum(SOURCE_KINDS),
});
// Where a signal went once it was sorted: a story, a problem, a GitHub issue,
// Build (a bug or an update whose GitHub issue is not made yet), or it was
// simply answered.
const wentToSchema = z.discriminatedUnion("to", [
    z.strictObject({ to: z.literal("story"), id }),
    z.strictObject({ to: z.literal("problem"), id }),
    z.strictObject({ to: z.literal("ticket"), issue }),
    z.strictObject({ to: z.literal("build") }),
    z.strictObject({ to: z.literal("answered") }),
]);
export const SORTED_AS = [
    "need",
    "bug",
    "question",
    "update",
    "unsure",
];
// One thing someone said or did, or one error. Signals stay single and are
// never counted, except machine errors, which say how often they happened (n).
export const signalSchema = z.strictObject({
    id,
    source: id,
    text,
    // The customer who said it, when known.
    who: id.nullable().default(null),
    when: z.string().default(""),
    n: z.number().int().positive().optional(),
    sortedAs: z.enum(SORTED_AS).default("unsure"),
    // The persona it sounds like; null while that is not clear.
    soundsLike: id.nullable().default(null),
    why: z.string().default(""),
    by: by.default(KOBOLD),
    // Null while it is not sorted yet.
    wentTo: wentToSchema.nullable().default(null),
});
// A made-up person who stands for a kind of user.
export const personaSchema = z.strictObject({
    id,
    name: text,
    role: text,
    description: z.string().default(""),
    wants: z.array(text).default([]),
    // What the persona is drawn from: interviews, customers, how people use it.
    basedOn: z.array(text).default([]),
});
// A real customer, who is like one of the personas.
export const customerSchema = z.strictObject({ id, name: text, persona: id });
// What the team is really solving for a persona, behind several of their
// problems.
export const realProblemSchema = z.strictObject({
    id,
    persona: id,
    title: text,
    description: z.string().default(""),
    by,
});
// A few signals read together, with what is behind them (the reading).
export const problemSchema = z.strictObject({
    id,
    persona: id,
    title: text,
    reading: z.string().default(""),
    by,
    // True when nobody said it yet: it only comes from an idea's story.
    assumed: z.boolean().default(false),
    realProblem: id.nullable().default(null),
});
// A moment in a story. Where it happens is a free label; signals as evidence
// make it seen, none leaves it guessed. One scene of a story breaks.
const sceneSchema = z.strictObject({
    text,
    where: z.string().nullable().default(null),
    evidence: z.array(id).default([]),
    breaks: z.boolean().default(false),
});
// What a persona goes through, told in scenes, up to where it breaks at one
// problem.
export const storySchema = z.strictObject({
    id,
    persona: id,
    title: text,
    starts: z.string().default(""),
    wants: z.string().default(""),
    scenes: z.array(sceneSchema).min(1),
    // What the persona does instead, since it breaks.
    instead: z
        .strictObject({ text, evidence: z.array(id).default([]) })
        .nullable()
        .default(null),
    // Why the story turned out wrong; null while it holds.
    wrong: text.nullable().default(null),
    isNew: z.boolean().default(false),
    // Written from signals, or from an idea (then all its scenes are guessed).
    from: z.union([
        z.strictObject({ signals: z.array(id).min(1) }),
        z.strictObject({ idea: id }),
    ]),
    problem: id.nullable().default(null),
});
// An idea, and what the team thinks it would do (weThink). It starts from a
// problem or from a team member.
export const ideaSchema = z.strictObject({
    id,
    title: text,
    weThink: text,
    origin: z.discriminatedUnion("from", [
        z.strictObject({ from: z.literal("problem"), id }),
        z.strictObject({ from: z.literal("person"), name: text }),
    ]),
    problems: z.array(id).default([]),
    // The persona it is for, when it addresses no problem yet.
    persona: id.nullable().default(null),
});
// A version of an idea: its branch is the interactive prototype.
export const versionSchema = z.strictObject({
    idea: id,
    // Its letter within the idea ("A", "B2").
    key: id,
    name: text,
    branch: text,
    madeBy: z.array(text).min(1),
    surface: z.enum(["phone", "desktop"]),
    sharedAt: z.string().nullable().default(null),
    // The team members who picked it.
    picks: z.array(text).default([]),
    // A picture of it, when someone made one (a web address); none is needed.
    thumbnail: z.string().nullable().default(null),
});
// A GitHub issue the records know: an idea's version sent to Build, or a fix
// or an update straight from a signal, and the problems it is for.
export const ticketLinkSchema = z.strictObject({
    issue,
    kind: z.enum(["idea", "fix", "update"]),
    from: z.union([
        z.strictObject({ idea: id, version: id }),
        z.strictObject({ signal: id }),
    ]),
    problems: z.array(id).default([]),
    // The day it was made (YYYY-MM-DD), to tell what was heard since; empty
    // when not known.
    on: z.string().default(""),
});
// The answer to "did it work?" once an issue is closed.
export const outcomeSchema = z.strictObject({
    issue,
    worked: z.enum(["yes", "no", "unchecked"]),
    // What was seen, and from which source.
    seen: z.strictObject({ text, source: id }).nullable().default(null),
    by,
    on: text,
});
export const RECORD_SCHEMAS = {
    sources: sourceSchema,
    signals: signalSchema,
    personas: personaSchema,
    customers: customerSchema,
    realProblems: realProblemSchema,
    problems: problemSchema,
    stories: storySchema,
    ideas: ideaSchema,
    versions: versionSchema,
    ticketLinks: ticketLinkSchema,
    outcomes: outcomeSchema,
};
// What one record of each kind is called, in what the checks say.
export const RECORD_NAMES = {
    sources: "Source",
    signals: "Signal",
    personas: "Persona",
    customers: "Customer",
    realProblems: "Real problem",
    problems: "Problem",
    stories: "Story",
    ideas: "Idea",
    versions: "Version",
    ticketLinks: "Ticket",
    outcomes: "Outcome",
};
export const KINDS = Object.keys(RECORD_SCHEMAS);
export const recordsSchema = z.strictObject({
    sources: z.array(sourceSchema).default([]),
    signals: z.array(signalSchema).default([]),
    personas: z.array(personaSchema).default([]),
    customers: z.array(customerSchema).default([]),
    realProblems: z.array(realProblemSchema).default([]),
    problems: z.array(problemSchema).default([]),
    stories: z.array(storySchema).default([]),
    ideas: z.array(ideaSchema).default([]),
    versions: z.array(versionSchema).default([]),
    ticketLinks: z.array(ticketLinkSchema).default([]),
    outcomes: z.array(outcomeSchema).default([]),
});
// A record's key within its kind: its id; a version's idea and letter; an
// issue's number.
export function keyOf(record) {
    if ("id" in record)
        return record.id;
    if ("issue" in record)
        return String(record.issue);
    return versionKey(record.idea, record.key);
}
export function versionKey(idea, key) {
    return `${idea}/${key}`;
}
// A signal brought in from outside (the import API, later the connectors):
// what was said, where, by whom and when. Sorting it is the kobold's.
export const importSignalSchema = signalSchema
    .pick({
    source: true,
    text: true,
    who: true,
    when: true,
    n: true,
})
    .extend({ id: id.optional() });
